/* State oracle for src/tu/grtdonkey.rs (generated by gen_target_stage.py): the game TU #included verbatim
 * (shipping contraction via run.py), every callee outside it a tracing stub, cases on a synthetic
 * state from the shared seeded stream. tests/tu_grtdonkey.rs replays them. */
#include "melee/gr/grtdonkey.c"
#include "oracle.h"
#include "tu_gr_common.h"
#include "tu_grtdonkey_stubs.inc"

static void state(void)
{
    printf("rs %u\n", ORS);
    printf("si %d %d\n", (int) stage_info.unk8C.b4, (int) stage_info.unk8C.b5);
    DUMPARENA();
    state_end();
}

#define FN(x) fnreg(#x, (void*) x)
int main(void)
{
    int c;
    arena_init();
    SIZE(Ground);
    SIZE(HSD_GObj);
    SIZE(HSD_JObj);
    SIZE(StageCallbacks);
    SIZE(StageData);
    reg("cb", grTDk_StageCallbacks, sizeof(grTDk_StageCallbacks));
    reg("sd", &grTDk_StageData, sizeof(grTDk_StageData));
    reg("dat", grTDk_StageData.data1, 16);
    FN(grTDonkey_80220228);
    FN(grTDonkey_OnInit);
    FN(grTdonkey_UnkStage0_OnLoad);
    FN(grTdonkey_UnkStage0_OnStart);
    FN(grTDonkey_802202C4);
    FN(grTDonkey_802202CC);
    FN(grTDonkey_802204FC);
    FN(grTDonkey_80220504);
    FN(stageGObj0_OnInit);
    FN(grTDonkey_802203E0);
    FN(grTDonkey_802203E8);
    FN(grTDonkey_802203EC);
    FN(stageGObj1_OnInit);
    FN(grTDonkey_802204D0);
    FN(stageGObj1_GObjProc);
    FN(grTDonkey_802204F8);
    FN(stageGObj2_OnInit);
    FN(grTDonkey_80220440);
    FN(stageGObj2_GObjProc);
    FN(grTDonkey_8022047C);
    fnreg("grDisplay_801C5DB0", (void*) grDisplay_801C5DB0);
    DUMP("cb", grTDk_StageCallbacks);
    DUMP("sd", grTDk_StageData);
    state_end();

    for (c = 0; c < 60; c++) { /* grTDonkey_802202CC and the callbacks it installs */
        CASE(c);
        rseed(100 + c);
        gr_reset();
        stage_info.unk8C.b4 = rnd() & 1;
        stage_info.unk8C.b5 = rnd() & 1;
        printf("r"); TRP(grTDonkey_802202CC(c % 3)); printf("\n");
        state();
    }
    for (c = 0; c < 20; c++) { /* OnInit / OnStart / OnLoad / OnDemoInit */
        CASE(1000 + c);
        rseed(2000 + c);
        gr_reset();
        grTDonkey_OnInit();
        state();
        grTdonkey_UnkStage0_OnStart();
        grTdonkey_UnkStage0_OnLoad();
        grTDonkey_80220228((int) rnd());
        state();
    }
    for (c = 0; c < 12; c++) { /* every stage callback of the three gobjs */
        HSD_GObj* g;
        CASE(2000 + c);
        rseed(3000 + c);
        gr_reset();
        g = mkgobj();
        stageGObj0_OnInit(g); state();
        printf("r %d\n", (int) grTDonkey_802203E0(g));
        grTDonkey_802203E8(g); grTDonkey_802203EC(g); state();
        stageGObj1_OnInit(g); state();
        printf("r %d\n", (int) grTDonkey_802204D0(g));
        stageGObj1_GObjProc(g); grTDonkey_802204F8(g); state();
        stageGObj2_OnInit(g); state();
        printf("r %d\n", (int) grTDonkey_80220440(g));
        stageGObj2_GObjProc(g); grTDonkey_8022047C(g); state();
        printf("r %d\n", (int) grTDonkey_802202C4());
        printf("r"); TRP(grTDonkey_802204FC((int) rnd())); printf("\n");
        {
            Vec3 v;
            int a1;
            HSD_JObj* j;
            v.x = rf(); v.y = rf(); v.z = rf();
            a1 = (int) rnd();
            j = mkjobj();
            printf("r %d\n", (int) grTDonkey_80220504(&v, a1, j));
        }
        state();
    }
    return 0;
}
